describe("doctests of sympy.functions.elementary.exponential", () => {
  it("exp(-x).as_numer_denom()", () => {
    const x = new Sym('x');
    const v1 = asNumerDenom(exp(mul(-1, x)));
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(1, exp(x))');
  });
  it("exp(x).as_numer_denom()", () => {
    const x = new Sym('x');
    const v1 = exp(x);
    expect(sympyStr([v1, at(asNumerDenom(v1), 1)], 't')).toBe('(exp(x), 1)');
  });
  it("LambertW(1.2)", () => {
    expect(sympyStr(LambertW(new Float(1.2)))).toBe('0.635564016364870');
  });
  it("LambertW(1.2, -1).n()", () => {
    expect(sympyStr(LambertW(new Float({ man: 5404319552844595n, exp: -52n }, 53), rational(-1)).evalf(15, {}))).toBe('-1.34747534407696 - 4.41624341514535*I');
  });
  it("LambertW(-1).is_real", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("exp(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(exp(x))).toBe('exp(x)');
  });
  it("exp(x).diff(x)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(exp(x), x))).toBe('exp(x)');
  });
  it("exp(I*pi)", () => {
    expect(sympyStr(exp(mul(pi, I)))).toBe('-1');
  });
  it("exp(x).as_real_imag()", () => {
    const x = new Sym('x');
    const v1 = asRealImag(exp(x));
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(exp(re(x))*cos(im(x)), exp(re(x))*sin(im(x)))');
  });
  it("exp(1).as_real_imag()", () => {
    expect(sympyStr([E, at(asRealImag(E), 1)], 't')).toBe('(E, 0)');
  });
  it("exp(I).as_real_imag()", () => {
    const v1 = asRealImag(exp(I));
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(cos(1), sin(1))');
  });
  it("exp(1+I).as_real_imag()", () => {
    const v1 = asRealImag(exp(add(1, I)));
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(E*cos(1), E*sin(1))');
  });
  it("exp(2*pi*I)", () => {
    expect(sympyStr(exp(mul(2, pi, I)))).toBe('1');
  });
  it("exp_polar(2*pi*I)", () => {
    expect(sympyStr(expPolar(mul(2, pi, I)))).toBe('exp_polar(2*I*pi)');
  });
  it("exp_polar(2)*exp_polar(3)", () => {
    expect(sympyStr(fn('exp_polar', [rational(2)]).mul(fn('exp_polar', [rational(3)])))).toBe('exp_polar(5)');
  });
  it("log(8, 2)", () => {
    expect(sympyStr(log(8, 2))).toBe('3');
  });
  it("log(S(8)/3, 2)", () => {
    expect(sympyStr(log(rational(8, 3), 2))).toBe('-log(3)/log(2) + 3');
  });
  it("log(-1 + I*sqrt(3))", () => {
    expect(sympyStr(log(add(-1, mul(I, pow(3, rational(1, 2))))))).toBe('log(2) + 2*I*pi/3');
  });
  it("log(x).as_real_imag()", () => {
    const x = new Sym('x');
    const v1 = asRealImag(log(x));
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(log(Abs(x)), arg(x))');
  });
  it("log(I).as_real_imag()", () => {
    const v1 = asRealImag(mul(rational(1, 2), pi, I));
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(0, pi/2)');
  });
  it("log(1 + I).as_real_imag()", () => {
    const v1 = log(pow(2, rational(1, 2)));
    expect(sympyStr([v1, at(asRealImag(add(mul(rational(1, 4), pi, I), v1)), 1)], 't')).toBe('(log(sqrt(2)), pi/4)');
  });
  it("log(I*x).as_real_imag()", () => {
    const x = new Sym('x');
    const v1 = asRealImag(log(mul(I, x)));
    expect(sympyStr([at(v1, 0), at(v1, 1)], 't')).toBe('(log(Abs(x)), arg(I*x))');
  });
});

